class GaloisDetokenizer:
    """Detokenizer that is a right adjoint of ``tokenize``.

    The tokenizer maps every character of a string to a single token, using
    the special symbol ``"Ġ"`` for the space character.  The detokenizer must
    undo exactly that mapping so that ``tokenize(detokenize(tokenize(s)))``
    is identical to ``tokenize(s)`` for every input string ``s``.
    """

    SPACE_TOKEN = "Ġ"

    def detokenize(self, tokens: list[str]) -> str:
        if tokens is None:
            return ""

        pieces = []
        for token in tokens:
            if token is None:
                # Skip ``None`` entries: they carry no string content.
                continue
            if token == self.SPACE_TOKEN:
                pieces.append(" ")
            elif self.SPACE_TOKEN in token:
                # Multi-character tokens (never produced by ``tokenize``, but
                # handled for robustness): replace every occurrence of the
                # space marker so no information is lost and re-tokenizing the
                # result yields the original token sequence.
                pieces.append(token.replace(self.SPACE_TOKEN, " "))
            else:
                pieces.append(token)
        return "".join(pieces)

