class UnitCounitDetokenizer:
    """Adjoint detokenizer for the character/Ġ tokenizer.

    The tokenizer T maps every character to its own token, encoding a space as
    the special marker "Ġ".  The detokenizer D is its adjoint, so that the
    algebraic unit property holds for every string s:

        T(D(T(s))) == T(s)

    Since T is injective at the string level (D is its exact inverse), we also
    obtain the stronger round-trip property D(T(s)) == s.
    """

    @staticmethod
    def _decode_token(token) -> str:
        if token is None:
            return ""
        if not isinstance(token, str):
            token = str(token)
        # Restore the GPT-style space marker.  The replacement is applied inside
        # each token rather than to the joined string, so multi-character tokens
        # are handled consistently and marker-free tokens are left untouched.
        return token.replace("Ġ", " ")

    def detokenize(self, tokens: list[str]) -> str:
        if tokens is None:
            return ""
        return "".join(self._decode_token(token) for token in tokens)

